cd /tmp/vally-eval-trial-UmsVtk && mkdir -p tests/CheckoutPricing.UnitTests/Pricing && cat > tests/CheckoutPricing.UnitTests/Pricing/GoldDiscountTests.cs <<'E'
using System.Linq;
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var pricingTypes = new[] { typeof(ApplicationMarker).Assembly, typeof(DomainMarker).Assembly }
            .SelectMany(a => a.GetTypes())
            .Where(t => t.IsPublic && t != typeof(ApplicationMarker) && t != typeof(DomainMarker))
            .ToList();

        Assert.True(pricingTypes.Count > 0,
            "No checkout/pricing behaviour exists: the only production types are the empty marker classes, so a payable total of 95.00 cannot be produced.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Assert|No checkout|Passed!|Failed!" | head

